; keys.asm -- chapter 3: the keyboard rows, and three more ports
; generated by gen03.py
        INCLUDE "msx.inc"
        OUTPUT "keys.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 1
        ld c, 0
        ld hl, t_head
        call puts
        ld b, 15
        ld c, 0
        ld hl, t_psg
        call puts
        ld b, 17
        ld c, 0
        ld hl, t_aa
        call puts
        ld b, 19
        ld c, 0
        ld hl, t_a8
        call puts
        VDP_REG 1, $C0          ; display on; no interrupts: the program polls
main:   in a, (VDP_CTRL)        ; wait for the frame flag (bit 7 of the status)
        rlca
        jr nc, main
        ld b, 2
        ld e, 0                 ; the keyboard row
krow:   ld c, 0
        ld a, e
        call puthex
        in a, (PPI_C)
        and $F0                 ; keep the click, the LED and the cassette bits
        or e
        out (PPI_C), a          ; select the row
        in a, (PPI_B)           ; and read its eight keys: 0 = held down
        ld c, 4
        push af
        call fatbits
        pop af
        ld c, 13
        call puthex
        inc b
        inc e
        ld a, e
        cp 11
        jr nz, krow
        ld b, 15                ; the PSG's register 14: the joystick port
        ld c, 4
        ld a, 14
        out (PSG_ADDR), a
        in a, (PSG_READ)
        call byte
        ld b, 17                ; port $AA: the PPI's port C, as last written
        ld c, 4
        in a, (PPI_C)
        call byte
        ld b, 19                ; port $A8: the slots
        ld c, 4
        in a, (PPI_A)
        call byte
        jp main

; byte: A as eight boxes and two hexadecimal digits
byte:   push af
        call fatbits
        pop af
        inc c
        jp puthex

t_head: db "row port $A9", 0
t_psg:  db "R14", 0
t_aa:   db "$AA", 0
t_a8:   db "$A8", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret

; fatbits: A = a byte, drawn as 8 boxes, bit 7 first: a filled box for 1,
;          an empty one for 0. B = row, C = column; C moves on by 8.
;          Uses A. Keeps HL.
fatbits:
        push hl
        ld l, a
        ld h, 8
.bit:   ld a, 1                 ; an empty box ...
        rl l                    ; the next bit, into the carry
        jr nc, .put
        ld a, 2                 ; ... or a filled one
.put:   call putc
        inc c
        dec h
        jr nz, .bit
        pop hl
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
